def auc(x, y):
    """Trapezoid AUC of a curve, matching sklearn.metrics.auc."""
    order = np.argsort(x)
    x, y = np.asarray(x)[order], np.asarray(y)[order]
    dx = np.diff(x)
    return float(np.sum(dx * (y[1:] + y[:-1]) / 2.0))

